mapper.select:
select DATE_FORMAT(create_time, '%Y-%m-%d') as createTime, user_name as userName, count(*) as count
from b_event_tracking_cell_report
where is_delete=0

     and create_time>=#{startTime} and create_time<=#{endTime} 


    and user_name in

        #{item}


group by DATE_FORMAT(create_time, '%Y-%m-%d'),user_name

    order by ${orderField}

        ${descField}


        desc



    order by create_time desc

select DATE_FORMAT(create_time, '%Y-%m-%d') as createDate, user_name as userName, json_unquote(json_extract(request_param,'$.cidOrName')) as cidOrName, json_unquote(json_extract(request_param,'$.cid')) as cid, json_unquote(json_extract(request_param,'$.shortName')) as shortName, json_unquote(json_extract(request_param,'$.apiCodes')) as apiCodes, cell, create_time as createTime from b_event_tracking_cell_report where is_delete=0
and create_time>=#{startTime} and create_time<#{endTime}
and user_name in
#{item}
and request_param->'$.apiCodes' like CONCAT('%',#{apiCodes},'%')
order by ${orderField}
${descField}
desc
order by create_time desc
